// BEGIN CAPACITY MODULE
'use strict';

// Nominal workweek: successive days starting Monday; fractional last day supported.
function productiveDay(technician) {
  return Number(technician.hours_day) * Number(technician.productivity_rate ?? 100) / 100;
}

function productiveHours(technician, date) {
  const weekday = (new Date(date + 'T12:00:00').getDay() + 6) % 7;
  return technician.active ? productiveDay(technician) * Math.max(0, Math.min(1, Number(technician.days_week) - weekday)) : 0;
}

function planningCapacity(data, filter) {
  const team = data.team.filter(t => !filter.technician || String(t.id) === filter.technician);
  const orders = data.orders.filter(o => !['Concluída', 'Cancelada'].includes(o.status) &&
    o.scheduled_date >= filter.start && o.scheduled_date <= filter.end &&
    (!filter.technician || String(o.assignee_id) === filter.technician));
  const days = [];
  for (let date = filter.start; date <= filter.end; date = plus(date, 1)) {
    const daily = orders.filter(o => o.scheduled_date === date);
    const capacity = team.reduce((n, t) => n + productiveHours(t, date), 0);
    const load = daily.reduce((n, o) => n + Number(o.estimated_hours || 0), 0);
    // Sum per-person overload so another person's free hours cannot conceal a conflict.
    const excess = team.reduce((n, t) => n + Math.max(0,
      daily.filter(o => o.assignee_id == t.id).reduce((s, o) => s + Number(o.estimated_hours || 0), 0) - productiveHours(t, date)), 0);
    days.push({date, capacity, load, excess, count: daily.length});
  }
  const buckets = [];
  for (const day of days) {
    const key = filter.group === 'week' ? plus(day.date, -((new Date(day.date + 'T12:00:00').getDay() + 6) % 7)) : day.date;
    let bucket = buckets.at(-1);
    if (!bucket || bucket.key !== key) {
      bucket = {key, start: day.date, end: day.date, capacity: 0, load: 0, excess: 0, count: 0};
      buckets.push(bucket);
    }
    bucket.end = day.date;
    for (const field of ['capacity', 'load', 'excess', 'count']) bucket[field] += day[field];
  }
  return {orders, buckets, capacity: days.reduce((n, d) => n + d.capacity, 0),
    load: days.reduce((n, d) => n + d.load, 0), excess: days.reduce((n, d) => n + d.excess, 0),
    unassigned: orders.filter(o => !data.team.some(t => t.id == o.assignee_id))};
}

const capacityFilter = {technician: '', start: '', end: '', group: 'day'};

function capacityPanel() {
  if (!capacityFilter.start) {
    capacityFilter.start = plus(today(), -((new Date().getDay()+6)%7));
    capacityFilter.end = plus(capacityFilter.start, 6);
  }
  const result = planningCapacity(state, capacityFilter);
  const scale = Math.max(1, ...result.buckets.flatMap(b => [b.load, b.capacity]));
  const occupation = result.capacity ? num(result.load / result.capacity * 100) + '%' : 'Sem capacidade';
  const controls = `<div class="toolbar capacity-filters">
    <label>Técnico<select id="capacity-technician">${options(state.team.map(t => [t.id, t.name + (t.active ? '' : ' (inativo)')]), capacityFilter.technician, 'Todos os técnicos')}</select></label>
    <label>De<input type="date" id="capacity-start" value="${capacityFilter.start}"></label>
    <label>Até<input type="date" id="capacity-end" value="${capacityFilter.end}"></label>
    <label>Agrupar por<select id="capacity-group">${options([['day','Dias'],['week','Semanas']], capacityFilter.group, null)}</select></label>
    ${btn('Hoje','capacity-today')}${btn('Esta semana','capacity-week')}
  </div>`;
  const ceiling = Math.ceil(scale / 4) * 4;
  const chart = `<div class="planning-chart" role="group" aria-label="Gráfico de barras: carga prevista e capacidade útil em horas de trabalho">
    <div class="planning-legend"><span><i class="planned-key"></i>Carga prevista</span><span><i class="capacity-key"></i>Capacidade útil</span><span>HH · horas de trabalho</span></div>
    <div class="planning-chart-frame">
      <div class="planning-axis" aria-hidden="true">${[4,3,2,1,0].map(i=>`<span style="top:${(4-i)*25}%">${num(ceiling*i/4)}</span>`).join('')}</div>
      <div class="planning-scroll" tabindex="0" aria-label="Períodos do gráfico; role horizontalmente para ver mais datas">
        <div class="planning-plot" style="--periods:${result.buckets.length}">
          <div class="planning-grid" aria-hidden="true">${[0,25,50,75,100].map(y=>`<i style="top:${y}%"></i>`).join('')}</div>
          ${result.buckets.map(b=>{
            const range = dateLabel(b.start)+(b.end!==b.start?' — '+dateLabel(b.end):'');
            const occupation = b.capacity ? num(b.load/b.capacity*100)+'%' : 'Sem capacidade';
            const summary = `${range}: ${b.count} OS; carga prevista ${num(b.load)} HH; capacidade útil ${num(b.capacity)} HH; ocupação ${occupation}; sobrecarga ${num(b.excess)} HH. Clique para consultar as OS.`;
            return `<button class="planning-column" data-action="capacity-detail" data-start="${b.start}" data-end="${b.end}" aria-label="${esc(summary)}" title="${esc(summary)}">
              <span class="planning-bars" aria-hidden="true"><span class="planning-bar planned" style="height:${b.load/ceiling*100}%"><span>${num(b.load)}</span></span><span class="planning-bar available" style="height:${b.capacity/ceiling*100}%"><span>${num(b.capacity)}</span></span></span>
              <span class="planning-period">${dateLabel(b.start).slice(0,5)}${b.end!==b.start?'<br>— '+dateLabel(b.end).slice(0,5):''}</span>
              <span class="planning-caption">${b.count} OS · ${occupation}</span>
              <span class="planning-conflict ${b.excess?'text-red':''}">${b.excess?num(b.excess)+' HH de sobrecarga':'Sem sobrecarga'}</span>
            </button>`;
          }).join('')}
        </div>
      </div>
    </div>
    <p class="planning-hint">${capacityFilter.group==='week'?'Semanas':'Dias'} · Clique nas barras para consultar as OS. Em períodos longos, role o gráfico para os lados.</p>
  </div>`;
  return panel('OS planejadas × capacidade produtiva', `<div class="capacity-planning">${controls}
    <div class="stats">${stat('Carga prevista',num(result.load),'HH',`${result.orders.length} OS abertas com data programada`)}${stat('Capacidade útil',num(result.capacity),'HH','Somente técnicos ativos')}${stat('Ocupação',occupation,'','Carga prevista ÷ capacidade útil')}${stat('Saldo de capacidade',num(result.capacity-result.load),'HH',result.load>result.capacity?'Demanda acima da capacidade':'Capacidade menos carga prevista')}</div>
    ${result.excess ? `<div class="note warning">Sobrecarga por técnico/dia: <strong>${num(result.excess)} HH</strong>. Folgas de outros técnicos ou dias não compensam estes conflitos.</div>` : ''}
    ${result.unassigned.length ? `<div class="note warning">${result.unassigned.length} OS (${num(sum(result.unassigned,'estimated_hours'))} HH) sem técnico cadastrado: incluídas na carga, sem verificação individual de sobrecarga.</div>` : ''}
    ${chart}
    <details class="capacity-method"><summary>Critérios do cálculo</summary><p>HH = horas de trabalho. A carga usa as horas estimadas das OS abertas na data programada; concluídas, canceladas e sem data ficam fora. Cada OS concentra suas horas nessa data.</p><p>Capacidade útil = horas totais/dia × taxa de produtividade ÷ 100 × dias de trabalho no período. Como não há escala cadastrada, os dias/semana são contados consecutivamente a partir de segunda-feira (5 dias = segunda a sexta). Feriados, férias e ausências não são descontados. Frações de dia usam capacidade proporcional. Ajuste as horas totais e a taxa de produtividade em Equipe e capacidade.</p></details>
    </div>`, 'Filtre o período e o técnico; clique em um dia ou semana para consultar as atividades.');
}

document.addEventListener('change', e => {
  if (!e.target.id.startsWith('capacity-')) return;
  const key = e.target.id.slice(9), next = {...capacityFilter, [key]: e.target.value};
  if (!/^\d{4}-\d{2}-\d{2}$/.test(next.start) || !/^\d{4}-\d{2}-\d{2}$/.test(next.end) || next.start > next.end || (new Date(next.end) - new Date(next.start))/86400000 > 365) {
    toast('Escolha um período válido de até 366 dias.'); e.target.value = capacityFilter[key]; return;
  }
  Object.assign(capacityFilter, next); render();
});
document.addEventListener('click', e => {
  const button = e.target.closest('[data-action]');
  if (!button) return;
  if (button.dataset.action === 'capacity-today' || button.dataset.action === 'capacity-week') {
    const weekly = button.dataset.action === 'capacity-week';
    capacityFilter.start = weekly ? plus(today(), -((new Date().getDay()+6)%7)) : today();
    capacityFilter.end = plus(capacityFilter.start, weekly ? 6 : 0); render();
  }
  if (button.dataset.action === 'capacity-detail') {
    const result = planningCapacity(state, {...capacityFilter, start: button.dataset.start, end: button.dataset.end});
    showModal(`<div class="modal-head"><h2>Atividades · ${dateLabel(button.dataset.start)} — ${dateLabel(button.dataset.end)}</h2><button class="icon-button" data-action="close" aria-label="Fechar">×</button></div><div class="modal-body">${orderRows(result.orders)}</div>`);
  }
});

// END CAPACITY MODULE
'use strict';
const $ = (s, el=document) => el.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iso = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today = () => iso(new Date());
const plus = (s, n) => {const d = new Date(s+'T12:00:00'); d.setDate(d.getDate()+n); return iso(d);};
const dateLabel = v => v ? new Date(v+'T12:00:00').toLocaleDateString('pt-BR') : 'Não definida';
const num = (v, digits=1) => v==null ? '—' : Number(v).toLocaleString('pt-BR',{maximumFractionDigits:digits});
const money = v => Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const sum = (rows,key) => rows.reduce((s,r)=>s+Number(r[key]||0),0);
const openOrder = o => !['Concluída','Cancelada'].includes(o.status);
const statuses=['Aberta','Em planejamento','Aguardando material','Programada','Em execução','Concluída','Cancelada'];
const types=['Preventiva','Corretiva emergencial','Corretiva planejada','Preditiva','Inspeção','Melhoria'];
const shifts=['1º turno','2º turno','3º turno'];
const transitions={'Aberta':['Em planejamento','Aguardando material','Programada','Cancelada'],'Em planejamento':['Aguardando material','Programada','Cancelada'],'Aguardando material':['Em planejamento','Programada','Cancelada'],'Programada':['Em planejamento','Aguardando material','Em execução','Cancelada'],'Em execução':['Aguardando material','Concluída','Cancelada'],'Concluída':[],'Cancelada':[]};
const modules=[['dashboard','Visão geral','M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z'],['orders','Ordens de serviço','M8 4H5v17h14V4h-3 M9 2h6v5H9z M8 12h8 M8 16h6'],['schedule','Programação','M3 5h18v16H3z M3 10h18 M8 2v6 M16 2v6'],['annual','Cronograma 52 semanas','M4 4v16h17 M7 7h8 M11 11h10 M7 15h11'],['backlog','Backlog','M4 5h16 M4 12h16 M4 19h16 M8 3v4 M16 10v4 M10 17v4'],['plans','Planos de manutenção','M12 3v4 M12 17v4 M3 12h4 M17 12h4 M6 6l3 3 M15 15l3 3 M6 18l3-3 M15 9l3-3 M8 12a4 4 0 1 0 8 0a4 4 0 1 0-8 0'],['projects','Cronogramas de parada','M4 4v16h17 M7 7h8 M11 11h10 M7 15h11'],['kpis','Indicadores','M4 20V11h4v9 M10 20V4h4v16 M16 20v-9h4v9'],['failures','Falhas e confiabilidade','M12 3L2 21h20z M12 9v5 M12 17v1'],['assets','Máquinas e Linhas de Produção','M3 21V8l6 3V5l6 5V3h6v18z M7 15v3 M12 15v3 M17 15v3'],['team','Equipe e capacidade','M8 10a3 3 0 1 0 0-6a3 3 0 1 0 0 6 M2 21v-3a6 6 0 0 1 12 0v3 M16 4a3 3 0 0 1 0 6 M17 15a5 5 0 0 1 5 5'],['materials','Materiais','M3 7l9-4 9 4v13H3z M3 7l9 5 9-5 M12 12v8'],['settings','Dados e histórico','M4 4h16v16H4z M8 4v7h8V4 M8 16h8']];
let buttonLineOverride='', state, metric, page='dashboard', filters={text:'',status:'',area:'',shift:''}, assetFilters={text:'',line:'',criticality:''}, planFilters={text:'',line:'',specialty:''}, period={start:today().slice(0,8)+'01',end:today()}, scheduleDate=today(), annualYear=new Date().getFullYear(), annualWeek='', scheduleView='week', backlogView='board', toastTimer, renderVersion=0, selectedOrderIds=new Set();
const asset = id => state.assets.find(a=>a.id==id);
const person = id => state.team.find(t=>t.id==id);
const osCode = id => `OS-${String(id).padStart(4,'0')}`;
const badge = value => `<span class="badge ${['Concluída','Preventiva','Ativo'].includes(value)?'teal':['P1','Cancelada'].includes(value)?'red':['Aguardando material','Em execução'].includes(value)?'amber':['Programada','Preditiva'].includes(value)?'blue':''}">${esc(value)}</span>`;
const btn = (text,action,cls='',attrs='') => `<button class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const edit = (table,id,text='Editar') => btn(text,'edit','',`data-table="${table}" data-id="${id}"`);
const create = (table,text) => btn('+ '+text,'new','primary',`data-table="${table}"`);
const empty = text => `<div class="empty">${text}</div>`;
const options = (items,value='',blank='Todos') => (blank==null?'':`<option value="">${esc(blank)}</option>`)+items.map(i=>{const v=Array.isArray(i)?i[0]:i,l=Array.isArray(i)?i[1]:i;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('');
const stat = (label,value,unit,note,icon='↗') => `<div class="stat"><div class="stat-label">${label}<span class="stat-icon">${icon}</span></div><div class="stat-value">${value}<em>${unit||''}</em></div><div class="stat-note">${note||''}</div></div>`;
const panel = (title,body,sub='',action='') => `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<small>${sub}</small>`:''}</div>${action}</div>${body}</section>`;
const heading = (title,sub,action='') => `<div class="page-heading"><div><div class="eyebrow">PLANEJAMENTO E CONTROLE DA MANUTENÇÃO</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${action}</div></div>`;
const table = (headers,rows) => rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('Nenhum registro encontrado. Cadastre um item ou ajuste os filtros.');
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function api(path,method='GET',body){let response;try{response=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json','X-PCM-Client':'local'},body:body===undefined?undefined:JSON.stringify(body)});}catch{throw new Error(location.hostname==='127.0.0.1'||location.hostname==='localhost'?'Servidor desconectado. Abra Iniciar PCM.cmd e tente novamente.':'Conexão indisponível. Verifique sua internet e tente novamente.');}if(response.status===401||response.redirected){throw new Error('Sua sessão expirou. Recarregue a página para entrar novamente.');}let data;try{data=await response.json();}catch{throw new Error('Resposta inválida do servidor.');}if(!response.ok)throw new Error(data.error||'Não foi possível concluir a operação.');return data;}
function visibleOrders(){return state.orders.filter(o=>(!filters.area||(asset(o.asset_id)?.production_line||asset(o.asset_id)?.area)===filters.area)&&(!filters.shift||o.shift===filters.shift)&&(!filters.status||o.status===filters.status)&&(!filters.text||[osCode(o.id),o.title,asset(o.asset_id)?.name,asset(o.asset_id)?.tag].join(' ').toLocaleLowerCase().includes(filters.text.toLocaleLowerCase())));}
function orderAssetCell(a){const location=a?.production_line||a?.area||'Sem linha';return `<strong>${esc(a?.tag||'—')}</strong><small>${esc(a?.name||'Máquina não informada')}</small><small>${esc(location)}</small>`;}
function toolbar(withStatus=false,withText=false,withPeriod=false){return `<div class="toolbar">${withText?`<input id="search" aria-label="Buscar OS ou ativo" placeholder="Buscar OS, atividade ou ativo…" value="${esc(filters.text)}">`:''}${withPeriod?`<label class="filter-label">De<input type="date" id="period-start" value="${period.start}" aria-label="Início do período"></label><label class="filter-label">Até<input type="date" id="period-end" value="${period.end}" aria-label="Fim do período"></label>`:''}<select id="area-filter" aria-label="Filtrar linha de produção">${options([...new Set(state.assets.map(a=>a.production_line).filter(Boolean))].sort(),filters.area,'Todas as linhas')}</select><select id="shift-filter" aria-label="Filtrar turno">${options(shifts,filters.shift,'Todos os turnos')}</select>${withStatus?`<select id="status-filter" aria-label="Filtrar situação">${options(statuses,filters.status,'Todas as situações')}</select>`:''}${btn('Limpar filtros','clear-filters')}</div>`;}
function orderRows(orders,compact=false){return table(compact?['ORDEM / ATIVIDADE','MÁQUINA / LINHA','SITUAÇÃO','PRAZO']:['ORDEM / ATIVIDADE','MÁQUINA / LINHA','TIPO','PRIORIDADE','SITUAÇÃO','PROGRAMAÇÃO','RESPONSÁVEL'],orders.map(o=>{const a=asset(o.asset_id);let r=[`<button class="row-button" data-action="edit" data-table="orders" data-id="${o.id}"><strong>${osCode(o.id)}</strong><small class="order-title">${esc(o.title)}</small></button>`,orderAssetCell(a)];return compact?[...r,badge(o.status),`<span class="${openOrder(o)&&o.due_date&&o.due_date<today()?'text-red':''}">${dateLabel(o.due_date)}</span>`]:[...r,badge(o.type),`<span class="priority ${o.priority}">${o.priority}</span>`,badge(o.status),`${dateLabel(o.scheduled_date)}<small>${esc(o.shift)}</small>`,`${esc(person(o.assignee_id)?.name||'Não atribuído')}<small>${num(o.estimated_hours)} HH estimados</small>`];}));}
function selectableOrderRows(orders){const allSelected=orders.length>0&&orders.every(o=>selectedOrderIds.has(o.id));return table(['<input id="select-all-orders" type="checkbox" aria-label="Selecionar todas as ordens exibidas" '+(allSelected?'checked':'')+'>','ORDEM / ATIVIDADE','MÁQUINA / LINHA','TIPO','PRIORIDADE','SITUAÇÃO','PROGRAMAÇÃO','RESPONSÁVEL'],orders.map(o=>{const a=asset(o.asset_id);return [`<input class="order-select" type="checkbox" data-order-id="${o.id}" aria-label="Selecionar ${osCode(o.id)}" ${selectedOrderIds.has(o.id)?'checked':''}>`,`<button class="row-button" data-action="edit" data-table="orders" data-id="${o.id}"><strong>${osCode(o.id)}</strong><small class="order-title">${esc(o.title)}</small></button>`,orderAssetCell(a),badge(o.type),`<span class="priority ${o.priority}">${o.priority}</span>`,badge(o.status),`${dateLabel(o.scheduled_date)}<small>${esc(o.shift)}</small>`,`${esc(person(o.assignee_id)?.name||'Não atribuído')}<small>${num(o.estimated_hours)} HH estimados</small>`];}));}
function timelineChart(){const weeks=[];for(let i=5;i>=0;i--){const end=plus(today(),-i*7),start=plus(end,-6);weeks.push({start,end,opened:state.orders.filter(o=>start<=o.requested_date&&o.requested_date<=end).length,closed:state.orders.filter(o=>o.status==='Concluída'&&start<=o.completed_date&&o.completed_date<=end).length});}const max=Math.max(1,...weeks.flatMap(w=>[w.opened,w.closed]));return `<div class="chart">${weeks.map(w=>`<div class="chart-col"><div class="chart-number">${w.opened} / ${w.closed}</div><div class="bars"><div class="bar" style="height:${w.opened/max*100}%" title="${w.opened} abertas"></div><div class="bar dark" style="height:${w.closed/max*100}%" title="${w.closed} concluídas"></div></div><span class="chart-label">${dateLabel(w.start).slice(0,5)}</span></div>`).join('')}</div><div class="legend"><span><i class="pale"></i>Abertas</span><span><i></i>Concluídas</span><span>6 semanas • todas as áreas</span></div>`;}
function distribution(){const colors=['#188e7b','#63bba3','#e7ba68','#86aab8','#cbd8dd'];let total=state.orders.filter(openOrder).length,cumulative=0;let data=types.map((t,i)=>({name:t,n:state.orders.filter(o=>openOrder(o)&&o.type===t).length,color:colors[i]}));let gradient=data.map(d=>{const start=cumulative;cumulative+=total?d.n/total*100:0;return `${d.color} ${start}% ${cumulative}%`;}).join(',');return `<div class="distribution"><div class="donut" style="background:${total?'conic-gradient('+gradient+')':'#e7edef'}"><div class="donut-center"><strong>${total}</strong><small>OS EM ABERTO</small></div></div><div class="dist-list">${data.map(d=>`<div class="dist-row"><i style="background:${d.color}"></i>${d.name}<strong>${d.n}</strong></div>`).join('')}</div></div><div class="panel-bottom">Carteira atual • concluídas e canceladas excluídas</div>`;}
function dashboard(){const open=state.orders.filter(openOrder),crit=open.filter(o=>o.priority==='P1'),latePlans=state.plans.filter(p=>p.active&&p.next_date<=today()),lowStock=state.materials.filter(m=>m.quantity<m.minimum);return heading('Sua manutenção, sob controle.','Uma visão integrada das prioridades, da execução e da saúde da sua operação.',btn('Exportar OS','export-orders')+create('orders','Nova ordem de serviço'))+(state.demo?`<div class="demo-banner"><span>◈ <strong>Ambiente de demonstração</strong> · Dados fictícios de uma fábrica de lavadoras. Alterações são salvas ${state.storage==='cloudflare'?'na sua base online':'neste computador'}.</span><a href="#settings">Gerenciar dados →</a></div>`:'')+`<div class="stats">${stat('Ordens em aberto',metric.backlog_count,'OS',`${num(metric.backlog_hours)} HH na carteira`,'▤')}${stat('Concluídas no mês',metric.completed,'OS',`De ${dateLabel(today().slice(0,8)+'01')} a ${dateLabel(today())}`,'✓')}${stat('Aderência à programação',num(metric.adherence),'%',`${metric.on_time} de ${metric.planned} OS devidas no mês`,'◷')}${stat('Custo realizado no mês',money(metric.cost),'','Mão de obra + materiais das OS concluídas','↗')}</div>${capacityPanel()}<div class="dashboard-grid"><div>${panel('Fluxo de ordens de serviço',timelineChart(),'Entradas e conclusões por semana')}${panel('Prioridades da carteira',orderRows([...open].sort((a,b)=>a.priority.localeCompare(b.priority)||a.requested_date.localeCompare(b.requested_date)).slice(0,5),true),'Atividades que merecem sua atenção','<a class="link" href="#orders">Ver todas →</a>')}</div><div>${panel('Composição do backlog',distribution(),'Distribuição por estratégia de manutenção')}${panel('Pontos de atenção',`<div class="alert-row"><span class="alert-symbol">!</span><div><strong>${crit.length} OS de prioridade P1</strong><small>Revise os impactos e defina a próxima ação.</small></div><a href="#backlog">→</a></div><div class="alert-row"><span class="alert-symbol">◷</span><div><strong>${latePlans.length} planos vencidos ou devidos hoje</strong><small>Gere e programe as próximas ordens.</small></div><a href="#plans">→</a></div><div class="alert-row"><span class="alert-symbol">▦</span><div><strong>${lowStock.length} materiais abaixo do mínimo</strong><small>Antecipe as necessidades de reposição.</small></div><a href="#materials">→</a></div>`)}${panel('Seu próximo passo',`<div class="capacity"><p class="subtitle">Abra uma OS, detalhe recursos, programe por turno e registre a execução. O fechamento atualiza os indicadores automaticamente.</p><div class="actions" style="margin-top:15px">${btn('Conhecer o fluxo','help')}</div></div>`)}</div></div>`;}
function ordersPage(){const rows=visibleOrders().sort((a,b)=>b.id-a.id),selected=rows.filter(o=>selectedOrderIds.has(o.id)).length;return heading('Ordens de serviço','Da solicitação ao encerramento, com responsabilidade e histórico.',btn('Exportar CSV','export-orders')+btn('Exportar Excel','export-orders-excel')+btn('Importar OS','import-orders')+btn(`Imprimir ordens${selected?' ('+selected+')':''}`,'print-selected-orders','',selected?'':'disabled')+create('orders','Nova OS'))+toolbar(true,true)+panel(`${rows.length} ordens encontradas`,selectableOrderRows(rows),'Marque as ordens desejadas e use “Imprimir ordens”.');}
function backlogPage(){const orders=visibleOrders().filter(openOrder).sort((a,b)=>a.priority.localeCompare(b.priority)||a.requested_date.localeCompare(b.requested_date));const groups=[['Solicitações',['Aberta','Em planejamento']],['Pendências',['Aguardando material']],['Programadas',['Programada']],['Em execução',['Em execução']]];return heading('Backlog de manutenção','Carteira atual priorizada. A data dos indicadores não altera este retrato.',create('orders','Nova OS'))+toolbar(false,true)+`<div class="stats">${stat('Carteira',orders.length,'OS','Todas as atividades não encerradas')}${stat('Carga estimada',num(sum(orders,'estimated_hours')),'HH','Soma das horas previstas')}${stat('Idade média',num(orders.length?orders.reduce((s,o)=>s+(new Date(today())-new Date(o.requested_date))/86400000,0)/orders.length:0),'dias','Desde a solicitação')}${stat('Prioridade crítica',orders.filter(o=>o.priority==='P1').length,'OS','Prioridade definida pelo planejador')}</div><div class="kanban">${groups.map(([label,states])=>{const list=orders.filter(o=>states.includes(o.status));return `<section class="kanban-col"><h3>${label}<span>${list.length}</span></h3>${list.map(o=>`<button class="job-card" data-action="edit" data-table="orders" data-id="${o.id}"><div class="card-top"><span class="link">${osCode(o.id)}</span><span class="priority ${o.priority}">${o.priority}</span></div><h3>${esc(o.title)}</h3><small>${esc(asset(o.asset_id)?.tag)} · ${esc(asset(o.asset_id)?.name||'Máquina não informada')} · ${esc(asset(o.asset_id)?.production_line||asset(o.asset_id)?.area||'Sem linha')}</small>${o.blocker?`<p class="blocker">${esc(o.blocker)}</p>`:''}<div class="card-foot"><span>${num(o.estimated_hours)} HH · ${esc(o.shift)}</span><span>${dateLabel(o.due_date).slice(0,5)}</span></div></button>`).join('')||empty('Sem ordens nesta etapa.')}</section>`;}).join('')}</div>`;}
function schedulePage(){const scheduled=visibleOrders().filter(o=>o.scheduled_date&&o.status!=='Cancelada'),d=new Date(scheduleDate+'T12:00:00');let start=scheduleDate,end=scheduleDate,body='';if(scheduleView==='week'){start=plus(scheduleDate,-((d.getDay()+6)%7));end=plus(start,6);}if(scheduleView==='month'){start=iso(new Date(d.getFullYear(),d.getMonth(),1));end=iso(new Date(d.getFullYear(),d.getMonth()+1,0));}if(scheduleView==='year'){start=`${d.getFullYear()}-01-01`;end=`${d.getFullYear()}-12-31`;}
const job=o=>{const a=asset(o.asset_id);return `<button class="calendar-job ${o.status==='Concluída'?'done':''}" data-action="edit" data-table="orders" data-id="${o.id}"><strong>${osCode(o.id)} · ${esc(o.shift)}</strong><br>${esc(o.title)}<small><b>Tipo: ${esc(o.type||'Não definido')}</b> · ${esc(a?.tag||'—')} · ${esc(a?.name||'Máquina não informada')} · ${esc(person(o.assignee_id)?.name||'Sem responsável')} · ${num(o.estimated_hours)} HH · ${esc(o.status)}</small></button>`;};
if(scheduleView==='day'){body=panel(dateLabel(start),`<div class="shift-grid">${shifts.map(s=>`<section><h3>${s}</h3>${scheduled.filter(o=>o.scheduled_date===start&&o.shift===s).map(job).join('')||empty('Nenhuma OS programada.')}</section>`).join('')}</div>`);}
if(scheduleView==='week'){body=`<div class="calendar">${Array.from({length:7},(_,i)=>{const day=plus(start,i);return `<section class="day ${day===today()?'is-today':''}"><div class="day-title">${new Date(day+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'short'})}<strong>${day.slice(8)}</strong></div>${scheduled.filter(o=>o.scheduled_date===day).map(job).join('')||'<small class="day-empty">Sem programação</small>'}</section>`;}).join('')}</div>`;}
if(scheduleView==='month'){const offset=(new Date(start+'T12:00:00').getDay()+6)%7,count=new Date(end+'T12:00:00').getDate();body=`<div class="panel table-wrap"><div class="month-grid">${['SEG','TER','QUA','QUI','SEX','SÁB','DOM'].map(w=>`<div class="weekday">${w}</div>`).join('')}${Array.from({length:Math.ceil((offset+count)/7)*7},(_,i)=>{const day=plus(start,i-offset),inside=day>=start&&day<=end;return `<div class="month-cell ${inside?'':'muted'}"><strong>${day.slice(8)}</strong>${inside?scheduled.filter(o=>o.scheduled_date===day).map(job).join(''):''}</div>`;}).join('')}</div></div>`;}
if(scheduleView==='year'){body=`<div class="year-grid">${Array.from({length:12},(_,i)=>{const month=`${d.getFullYear()}-${String(i+1).padStart(2,'0')}`,orders=scheduled.filter(o=>o.scheduled_date.startsWith(month));return `<button class="month-card" data-action="open-month" data-date="${month}-01"><h3>${new Date(month+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'long'})}</h3><div class="stat-value">${orders.length}<em>OS</em></div><small>${num(sum(orders,'estimated_hours'))} HH previstos · ${orders.filter(o=>o.status==='Concluída').length} concluídas</small></button>`;}).join('')}</div>`;}
const rangeOrders=scheduled.filter(o=>start<=o.scheduled_date&&o.scheduled_date<=end),conflicts=[];for(const t of state.team.filter(t=>t.active)){const days=[...new Set(rangeOrders.filter(o=>o.assignee_id===t.id&&openOrder(o)).map(o=>o.scheduled_date))];for(const day of days){const load=sum(rangeOrders.filter(o=>o.assignee_id===t.id&&o.scheduled_date===day&&openOrder(o)),'estimated_hours');if(load>productiveHours(t,day))conflicts.push(`${t.name}: ${num(load)} HH / ${num(productiveHours(t,day))} h produtivas em ${dateLabel(day)}`);}}
return heading('Programação','Distribua as ordens por data, responsável e turno. Clique em uma OS para reprogramar.',create('orders','Nova OS'))+toolbar()+`<div class="toolbar"><div class="tabs">${[['day','Diária'],['week','Semanal'],['month','Mensal'],['year','Anual']].map(([id,label])=>`<button data-action="schedule-view" data-view="${id}" class="${scheduleView===id?'active':''}">${label}</button>`).join('')}</div>${btn('←','period-prev')}<input id="schedule-date" type="date" value="${scheduleDate}" aria-label="Data da programação" style="flex:none;width:155px">${btn('→','period-next')}${btn('Hoje','schedule-today')}<span class="subtitle">${dateLabel(start)} — ${dateLabel(end)}</span></div>${conflicts.length?`<div class="note warning"><strong>Sobrecarga de recurso:</strong> ${conflicts.map(esc).join(' • ')}. Reprograme ou ajuste a capacidade.</div>`:''}${body}<div class="note">${rangeOrders.length} OS no período · ${num(sum(rangeOrders,'estimated_hours'))} HH previstos. A carga diária soma OS abertas por técnico; a capacidade usa o cadastro da equipe. Turnos são faixas de trabalho, sem horários de início/fim nesta versão.</div>${panel('Ainda sem programação',orderRows(visibleOrders().filter(o=>openOrder(o)&&!o.scheduled_date),true),'Abra uma OS e use “Programar” para definir data e responsável.')}`;}
function annualPlanPage(){
  const calendarStart=`${annualYear}-01-01`,calendarEnd=`${annualYear}-12-31`;
  const start=plus(calendarStart,-((new Date(calendarStart+'T12:00:00').getDay()+6)%7)),lastWeek=plus(calendarEnd,-((new Date(calendarEnd+'T12:00:00').getDay()+6)%7));
  const weekCount=Math.round((Date.parse(lastWeek+'T00:00:00Z')-Date.parse(start+'T00:00:00Z'))/604800000)+1;
  const weeks=Array.from({length:weekCount},(_,i)=>plus(start,i*7));
  const isoWeek=date=>{const d=new Date(date+'T00:00:00Z'),monday=Date.parse(date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+3-((d.getUTCDay()+6)%7));const year=d.getUTCFullYear(),jan4=Date.UTC(year,0,4),week1=jan4-((new Date(jan4).getUTCDay()+6)%7)*86400000;return `${year}-${String(Math.floor((monday-week1)/604800000)+1).padStart(2,'0')}`;};
  const weekKeys=weeks.map(isoWeek),weekChoices=weeks.map((date,i)=>({key:weekKeys[i],date}));
  const displayedWeeks=annualWeek?weeks.map((date,index)=>({date,index})).filter(w=>weekKeys[w.index]===annualWeek):weeks.map((date,index)=>({date,index}));
  const weekIndex=date=>{if(!date||date<calendarStart||date>calendarEnd)return -1;return Math.floor((Date.parse(date+'T00:00:00Z')-Date.parse(start+'T00:00:00Z'))/604800000);};
  const rows=state.plans.map(plan=>{
    const events=Array.from({length:weekCount},()=>[]),orders=state.orders.filter(o=>o.plan_id==plan.id&&o.status!=='Cancelada');
    const add=(date,type,label,order)=>{const i=weekIndex(date);if(i>=0)events[i].push({date,type,label,order});};
    for(const o of orders){
      const planned=o.due_date||o.scheduled_date||o.requested_date;
      if(planned)add(planned,planned<today()&&(openOrder(o)||(o.completed_date&&o.completed_date>planned))?'late':'planned','P',o);
      if(o.scheduled_date&&o.scheduled_date!==planned)add(o.scheduled_date,'rescheduled','R',o);
      if(o.status==='Concluída'&&o.completed_date)add(o.completed_date,'done','E',o);
    }
    if(plan.active&&Number(plan.interval_days)>0){
      let date=plan.next_date,guard=0;
      while(date<=calendarEnd&&guard++<500){
        if(date>=calendarStart&&!orders.some(o=>(o.due_date||o.scheduled_date||o.requested_date)===date))add(date,date<today()?'late':'planned','P',null);
        date=plus(date,Number(plan.interval_days));
      }
    }
    return {plan,events};
  });
  const cells=displayedWeeks.map(({date,index})=>`<div class="annual-week ${annualWeek?'selected':''}" title="Semana ISO ${weekKeys[index]} · ${dateLabel(date)}">S${weekKeys[index].slice(5)}<small>${dateLabel(date).slice(0,5)}</small></div>`).join('');
  const grid=rows.map(({plan,events})=>`<div class="annual-row-label"><button class="row-button" data-action="edit" data-table="plans" data-id="${plan.id}"><strong>${esc(plan.name)}</strong><small>${esc(asset(plan.asset_id)?.tag||'')} · ${esc(asset(plan.asset_id)?.name||'Máquina não informada')} · a cada ${num(plan.interval_days,0)} dias</small></button></div><div class="annual-row">${displayedWeeks.map(({date,index})=>{const items=events[index];return `<div class="annual-cell ${annualWeek?'selected':''}" title="${dateLabel(date)}${items.length?': '+items.map(x=>`${x.label==='P'?'Planejada':x.label==='R'?'Reprogramada':x.label==='E'?'Executada':'Atrasada'} · ${dateLabel(x.date)}${x.order?' · '+osCode(x.order.id):''}`).join('; '):''}">${items.map(x=>x.order?`<button class="annual-mark ${x.type}" data-action="edit" data-table="orders" data-id="${x.order.id}" aria-label="${x.label==='P'?'Planejada':x.label==='R'?'Reprogramada':x.label==='E'?'Executada':'Atrasada'} ${esc(x.order.title)} · ${dateLabel(x.date)}">${x.label}</button>`:`<span class="annual-mark ${x.type}" title="${dateLabel(x.date)} · Próxima ocorrência prevista">${x.label}</span>`).join('')}</div>`;}).join('')}</div>`).join('');
  const chosenIndex=annualWeek?weekKeys.indexOf(annualWeek):-1,weekActivities=chosenIndex<0?[]:rows.flatMap(({plan,events})=>events[chosenIndex].map(event=>({plan,...event}))).sort((a,b)=>a.date.localeCompare(b.date));
  const activityPanel=chosenIndex<0?'':panel(`Atividades da semana ${annualWeek.slice(5)}`,weekActivities.length?table(['DATA','PLANO','OCORRÊNCIA','ORDEM / AÇÃO'],weekActivities.map(item=>[dateLabel(item.date),esc(item.plan.name),item.label==='P'?'Planejada':item.label==='R'?'Reprogramada':item.label==='E'?'Executada':'Atrasada',item.order?`<button class="row-button" data-action="edit" data-table="orders" data-id="${item.order.id}">${osCode(item.order.id)} · ${esc(item.order.title)}</button>`:`Previsão do plano · ${edit('plans',item.plan.id,'Abrir plano')}`])):empty('Nenhuma ocorrência registrada ou prevista nesta semana.'),'Abra uma ordem ou plano para atualizar os dados daquela ocorrência.');
  return heading(`Cronograma de manutenção · ${annualYear}`,'Escolha uma semana ISO para focar as atividades do período e abrir as ordens ou planos correspondentes.',create('plans','Novo plano'))+`<div class="panel"><div class="panel-head"><div><h2>${annualWeek?'Semana '+annualWeek.slice(5):'Planos por semana'}</h2><small>${annualWeek?`${dateLabel(displayedWeeks[0]?.date)} a ${dateLabel(plus(displayedWeeks[0]?.date||calendarStart,6))}`:`${dateLabel(calendarStart)} a ${dateLabel(calendarEnd)} · ${weekCount} semanas`}</small></div><div class="annual-filters"><label class="annual-year-label">Ano<select id="annual-year">${Array.from({length:7},(_,i)=>annualYear-3+i).map(y=>`<option value="${y}" ${y===annualYear?'selected':''}>${y}</option>`).join('')}</select></label><label class="annual-year-label">Semana<select id="annual-week"><option value="">Todas as semanas</option>${weekChoices.map(({key,date})=>`<option value="${key}" ${key===annualWeek?'selected':''}>Semana ${key.slice(5)} · ${dateLabel(date).slice(0,5)}</option>`).join('')}</select></label></div></div><div class="annual-legend"><span><i class="planned"></i>Planejada</span><span><i class="rescheduled"></i>Reprogramada</span><span><i class="done"></i>Executada</span><span><i class="late"></i>Atrasada</span></div><div class="annual-scroll" tabindex="0" aria-label="Cronograma anual; role horizontalmente para percorrer as semanas"><div class="annual-grid" style="--week-count:${displayedWeeks.length||1}"><div class="annual-row-label annual-sticky">PLANO / ATIVO</div>${cells}${grid||'<div class="annual-empty">Cadastre planos de manutenção para visualizar as ocorrências.</div>'}</div></div>${activityPanel}<div class="panel-bottom">P = data prevista; R = data programada diferente do prazo previsto; E = conclusão registrada. Semanas identificadas pela numeração ISO, de segunda a domingo. As próximas ocorrências são estimadas pela periodicidade e só planos ativos geram previsões.</div></div>`;
}
function plansPage(){
  const lines=[...new Set(state.assets.map(a=>a.production_line||a.area).filter(Boolean))].sort();
  const specialties=[...new Set(state.plans.map(p=>p.specialty).filter(Boolean))].sort();
  const needle=planFilters.text.trim().toLocaleLowerCase();
  const rows=state.plans.filter(p=>{
    const a=asset(p.asset_id), haystack=[p.name,p.type,p.specialty,a?.tag,a?.name,a?.production_line,a?.area].join(' ').toLocaleLowerCase();
    return (!needle||haystack.includes(needle)) && (!planFilters.line||(a?.production_line||a?.area)===planFilters.line) && (!planFilters.specialty||p.specialty===planFilters.specialty);
  });
  const filterBar=`<div class="toolbar plans-filters"><input id="plans-search" aria-label="Buscar plano ou máquina" placeholder="Buscar plano, TAG ou máquina…" value="${esc(planFilters.text)}"><select id="plans-line-filter" aria-label="Filtrar linha">${options(lines,planFilters.line,'Todas as linhas')}</select><select id="plans-specialty-filter" aria-label="Filtrar especialidade">${options(specialties,planFilters.specialty,'Todas as especialidades')}</select>${btn('Limpar filtros','clear-plan-filters')}</div>`;
  return heading('Planos de manutenção','Rotinas periódicas vinculadas ao ativo, com geração controlada de ordens.',create('plans','Novo plano'))+filterBar+`<div class="filter-summary">${rows.length} de ${state.plans.length} planos encontrados</div><div class="cards">${rows.map(p=>`<article class="info-card"><div class="top">${badge(p.type)}${badge(p.active?'Ativo':'Inativo')}</div><h3>${esc(p.name)}</h3><p>${esc(asset(p.asset_id)?.tag)} · ${esc(asset(p.asset_id)?.name)}${(asset(p.asset_id)?.production_line||asset(p.asset_id)?.area)?` · ${esc(asset(p.asset_id)?.production_line||asset(p.asset_id)?.area)}`:''}</p><dl><div><dt>Periodicidade</dt><dd>A cada ${num(p.interval_days,0)} dias</dd></div><div><dt>Próxima ocorrência</dt><dd class="${p.next_date<today()?'text-red':''}">${dateLabel(p.next_date)}</dd></div><div><dt>Recursos previstos</dt><dd>${num(p.hours)} HH · ${esc(p.specialty)}</dd></div></dl><div class="actions">${edit('plans',p.id)}${p.active?btn('Gerar OS','generate','primary',`data-id="${p.id}"`):''}</div></article>`).join('')||empty('Nenhum plano encontrado. Ajuste os filtros ou cadastre um novo plano.')}</div><div class="note">Gerar OS cria uma solicitação em aberto e avança a próxima ocorrência pela periodicidade do plano. A programação depende de data e responsável. A geração é manual e uma mesma ocorrência não pode ser gerada duas vezes.</div>`;
}
function projectsPage(){return heading('Cronogramas de parada','Organize janelas de manutenção e acompanhe as ordens vinculadas.',create('projects','Novo cronograma'))+state.projects.map(p=>{const orders=state.orders.filter(o=>o.project_id===p.id),done=orders.filter(o=>o.status==='Concluída').length,days=Math.max(1,(new Date(p.end)-new Date(p.start))/86400000+1);return panel(esc(p.name),`<div class="project-summary"><span>${dateLabel(p.start)} → ${dateLabel(p.end)}</span><span>${esc(p.owner||'Sem coordenador')}</span><span>${done}/${orders.length} OS concluídas</span></div><div class="progress" style="margin:0 22px 18px"><span style="width:${orders.length?done/orders.length*100:0}%"></span></div><div class="table-wrap"><div class="gantt">${orders.map(o=>{const a=asset(o.asset_id),offset=o.scheduled_date?(new Date(o.scheduled_date)-new Date(p.start))/86400000:0,inside=o.scheduled_date&&o.scheduled_date>=p.start&&o.scheduled_date<=p.end;return `<div class="gantt-label"><button class="row-button" data-action="edit" data-table="orders" data-id="${o.id}">${osCode(o.id)} · ${esc(o.title)}<small>${esc(a?.tag||'—')} · ${esc(a?.name||'Máquina não informada')}</small></button></div><div class="gantt-track">${inside?`<span class="gantt-bar" style="left:${offset/days*100}%;width:${100/days}%" title="${dateLabel(o.scheduled_date)} · ${esc(o.status)}">${dateLabel(o.scheduled_date).slice(0,5)}</span>`:`<span class="subtitle" style="padding-left:16px">${o.scheduled_date?'Fora da janela: '+dateLabel(o.scheduled_date):'Sem programação'}</span>`}</div>`;}).join('')}</div></div>${!orders.length?empty('Nenhuma OS vinculada. Selecione este cronograma ao editar uma ordem.') :''}<div class="panel-bottom">${esc(p.notes)} · Cada barra representa o dia programado; não a duração em horas.</div>`,`${num(sum(orders,'estimated_hours'))} HH previstos`,edit('projects',p.id));}).join('');}
function kpisPage(){return heading('Indicadores de manutenção','Resultados calculados com as ordens salvas. Período por data de conclusão.',btn('Imprimir','print'))+toolbar(false,false,true)+`<div class="stats">${stat('OS concluídas',metric.completed,'OS',`${num(metric.completed_hours)} HH realizados`)}${stat('Aderência',num(metric.adherence),'%',`${metric.on_time} / ${metric.planned} ordens no prazo`)}${stat('MTTR registrado',num(metric.mttr),'h',`${metric.failures} corretivas com parada > 0`)}${stat('Custo realizado',money(metric.cost),'','Mão de obra + materiais')}</div><div class="stats">${stat('Backlog atual',num(metric.backlog_hours),'HH',`${metric.backlog_count} ordens abertas`)}${stat('Backlog / capacidade',num(metric.backlog_weeks,2),'semanas',`${num(metric.weekly_capacity)} HH semanais disponíveis`)}${stat('Manutenção proativa',num(metric.preventive_share),'%','Preventiva + preditiva + inspeção / concluídas')}${stat('Paradas registradas',num(metric.downtime),'h','Somatório das corretivas concluídas')}</div><div class="split">${panel('Composição das conclusões',table(['ESTRATÉGIA','CONCLUÍDAS','PARTICIPAÇÃO'],types.map(t=>[badge(t),metric.by_type[t],metric.completed?num(metric.by_type[t]/metric.completed*100)+'%':'—'])))}${panel('Como os indicadores são calculados',`<div class="metric-detail"><p><strong>Aderência:</strong> OS concluídas até a data programada ÷ OS com programação vencida no período (até hoje). Canceladas ficam fora. A reprogramação altera esta referência; não há congelamento de programação nesta versão.</p><p><strong>MTTR:</strong> horas de parada registradas ÷ corretivas concluídas com parada maior que zero. Cada OS é considerada um evento. Paradas simultâneas não são consolidadas.</p><p><strong>Backlog:</strong> todas as OS não concluídas e não canceladas, independentemente do período. Capacidade semanal = horas totais/dia × taxa de produtividade ÷ 100 × dias/semana dos técnicos ativos no turno selecionado. Não há alocação exclusiva de técnicos por área.</p><p><strong>Custo:</strong> HH reais × valor/hora + custo informado de materiais. O estoque não é baixado automaticamente.</p><p><strong>MTBF, disponibilidade e OEE:</strong> não calculados sem horas reais de operação, tempos consolidados de parada e dados de produção/qualidade.</p></div>`)}</div>`;}
function assetsPage(){const lines=[...new Set(state.assets.map(a=>a.production_line).filter(Boolean))].sort(),locations=[...new Set(state.assets.map(a=>a.production_line||a.area).filter(Boolean))].sort(),needle=assetFilters.text.trim().toLocaleLowerCase(),rows=state.assets.filter(a=>(!assetFilters.line||(a.production_line||a.area)===assetFilters.line)&&(!assetFilters.criticality||a.criticality===assetFilters.criticality)&&(!needle||[a.tag,a.name,a.production_line,a.area,a.manufacturer,a.model,a.serial].join(' ').toLocaleLowerCase().includes(needle)));const filterBar=`<div class="toolbar"><input id="asset-search" aria-label="Buscar máquina" placeholder="Buscar TAG, máquina, fabricante ou modelo…" value="${esc(assetFilters.text)}"><select id="asset-line-filter" aria-label="Filtrar linha de produção">${options(locations,assetFilters.line,'Todas as linhas / áreas')}</select><select id="asset-criticality-filter" aria-label="Filtrar criticidade">${options([['A','Classe A'],['B','Classe B'],['C','Classe C']],assetFilters.criticality,'Todas as classes')}</select>${btn('Limpar filtros','clear-asset-filters')}</div>`;return heading('Linhas de produção e máquinas','Organize cada linha com suas máquinas e mantenha áreas legadas identificadas.',create('assets','Nova máquina'))+filterBar+`<div class="cards">${lines.map(line=>`<article class="info-card"><div class="top"><span class="badge teal">LINHA DE PRODUÇÃO</span><span class="badge">${state.assets.filter(a=>a.production_line===line).length} máquinas</span></div><h3>${esc(line)}</h3><p>Ordens abertas: ${state.orders.filter(o=>asset(o.asset_id)?.production_line===line&&openOrder(o)).length}</p><div class="actions">${btn('Adicionar máquina','new','primary',`data-table="assets" data-line="${esc(line)}"`)}</div></article>`).join('')}</div>`+panel(`${rows.length} de ${state.assets.length} máquinas e ativos`,table(['TAG / MÁQUINA','LINHA DE PRODUÇÃO','CRITICIDADE','CARTEIRA ATUAL',''],rows.map(a=>[`<strong>${esc(a.tag)}</strong><small>${esc(a.name)}</small>`,a.production_line?esc(a.production_line):`<span class="muted">${esc(a.area||'Sem linha atribuída')}</span>`,badge('Classe '+a.criticality),`${state.orders.filter(o=>o.asset_id===a.id&&openOrder(o)).length} OS`,edit('assets',a.id)])));}
function teamPage(){return heading('Equipe e capacidade','Cadastre executantes por turno e dimensione a carga de manutenção.',create('team','Novo profissional'))+`<div class="stats">${shifts.map(s=>stat(s,num(state.team.filter(t=>t.active&&t.shift===s).reduce((n,t)=>n+productiveDay(t)*t.days_week,0)),'HH/semana',`${state.team.filter(t=>t.active&&t.shift===s).length} profissionais ativos`)).join('')}${stat('Carga da carteira',num(sum(state.orders.filter(openOrder),'estimated_hours')),'HH','Soma das estimativas de OS abertas')}</div>`+panel('Profissionais',table(['NOME','ESPECIALIDADE','TURNO','CAPACIDADE','SITUAÇÃO',''],state.team.map(t=>[esc(t.name),esc(t.specialty),esc(t.shift),`${num(t.hours_day)} h/dia · ${num(t.days_week)} dias/semana<br><small>${num(t.productivity_rate ?? 100)}% · ${num(productiveDay(t))} h produtivas/dia</small>`,badge(t.active?'Ativo':'Inativo'),edit('team',t.id)])))+`<div class="note">Capacidade produtiva = horas totais × taxa de produtividade. Exemplo: 8 h × 50% = meta de 4 h produtivas por dia. A programação sinaliza sobrecarga por pessoa e data.</div>`;}
function materialsPage(){return heading('Materiais e sobressalentes','Posição de estoque e necessidades de reposição. Atualização manual.',create('materials','Novo material'))+panel('Estoque de manutenção',table(['CÓDIGO / MATERIAL','LOCAL','ESTOQUE','MÍNIMO','VALOR UNITÁRIO','SITUAÇÃO',''],state.materials.map(m=>[`<strong>${esc(m.code)}</strong><small>${esc(m.name)}</small>`,esc(m.location),`${num(m.quantity)} ${esc(m.unit)}`,num(m.minimum),money(m.unit_cost),badge(m.quantity<m.minimum?'Repor':'Disponível'),edit('materials',m.id)])))+`<div class="note">O cadastro controla saldos informados manualmente. Registre os custos efetivamente consumidos em cada OS; salvar ou concluir uma ordem não movimenta automaticamente este estoque.</div>`;}
function failuresPage(){const rows=visibleOrders().filter(o=>o.type==='Corretiva'&&o.status==='Concluída'&&o.completed_date>=period.start&&o.completed_date<=period.end);return heading('Falhas e confiabilidade','Histórico de corretivas e causas registradas para orientar análise e melhorias.')+toolbar(false,false,true)+panel('Ocorrências encerradas',table(['OS / ATIVO','FALHA','CAUSA REGISTRADA','AÇÃO EXECUTADA','PARADA','CONCLUSÃO'],rows.map(o=>[`<button class="row-button" data-action="edit" data-table="orders" data-id="${o.id}">${osCode(o.id)}</button><small>${esc(asset(o.asset_id)?.tag)} · ${esc(asset(o.asset_id)?.name||'Máquina não informada')}</small>`,esc(o.failure),esc(o.cause),esc(o.action),num(o.downtime_hours)+' h',dateLabel(o.completed_date)])))+`<div class="note">Uma causa registrada como “Em análise” precisa de investigação posterior. Horas de parada representam tempo do equipamento; horas reais da OS representam trabalho do executante.</div>`;}
function settingsPage(){return heading('Dados e histórico',(state.storage==='cloudflare'?'Sua base fica online, com acesso restrito.':'Sua base fica neste computador.')+' Mantenha cópias de segurança periódicas.')+`<div class="split">${panel('Cópia de segurança',`<div class="capacity"><p class="subtitle">Exporte todos os cadastros e ordens em JSON. Restaurar substitui os dados atuais e exige confirmação. Guarde o arquivo em local seguro.</p><div class="actions" style="margin-top:18px">${btn('Baixar backup','backup','primary')}${btn('Restaurar backup','restore')}</div><input type="file" id="restore-file" accept=".json,application/json" hidden></div>`)}${panel('Ambiente de trabalho',`<div class="capacity"><p class="subtitle">${state.demo?'A base contém exemplos fictícios e quaisquer registros que você adicionou durante a demonstração. Iniciar uma base vazia apaga TODOS eles. Faça um backup antes.':(state.storage==='cloudflare'?'Base de trabalho individual. Seus registros ficam salvos online e permanecem após as atualizações do sistema.':'Base de trabalho individual. Todos os registros são persistidos em SQLite na pasta data.')}</p>${state.demo?`<div class="actions" style="margin-top:18px">${btn('Iniciar base vazia','clear-demo','danger')}</div>`:''}</div>`)}</div>`+panel('Histórico de alterações',table(['DATA / HORA','AÇÃO','MÓDULO','REGISTRO'],state.audit.map(a=>[esc(a.time.replace('T',' ')),esc(a.event),esc(({orders:'Ordens de serviço',assets:'Ativos',team:'Equipe',materials:'Materiais',plans:'Planos',projects:'Cronogramas'})[a.entity]||a.entity),a.record_id||'—'])),'Últimas 100 alterações registradas na base.');}
async function render(){const ticket=++renderVersion;const title=modules.find(m=>m[0]===page)?.[1]||'Visão geral';$('#breadcrumb').textContent=title;$('#nav').innerHTML=modules.map(([id,label,path],i)=>(i===0?'<div class="nav-label">GESTÃO DA MANUTENÇÃO</div>':i===9?'<div class="nav-label">RECURSOS E BASE DE DADOS</div>':'')+`<a href="#${id}" class="${page===id?'active':''}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="${path}"/></svg>${label}${id==='orders'?`<span class="count">${state.orders.filter(openOrder).length}</span>`:''}</a>`).join('');
try{if(['dashboard','kpis'].includes(page)){const p=page==='dashboard'?{start:today().slice(0,8)+'01',end:today()}:period;metric=await api('metrics?'+new URLSearchParams({...p,area:page==='dashboard'?'':filters.area,shift:page==='dashboard'?'':filters.shift}));if(ticket!==renderVersion)return;}const views={dashboard,orders:ordersPage,backlog:backlogPage,schedule:schedulePage,annual:annualPlanPage,plans:plansPage,projects:projectsPage,kpis:kpisPage,assets:assetsPage,team:teamPage,materials:materialsPage,failures:failuresPage,settings:settingsPage};$('#main').innerHTML=(views[page]||dashboard)();}catch(error){$('#main').innerHTML=heading('Não foi possível carregar','Verifique sua conexão e tente novamente.')+`<div class="note">${esc(error.message)}</div>`+btn('Tentar novamente','reload');}}
async function refresh(){state=await api('state');const cloud=state.storage==='cloudflare';$('.local-badge').textContent=cloud?'● Base online':'● Banco local';$('.sidebar-bottom small').textContent=cloud?'Acesso privado · individual':'Ambiente local · individual';await render();}
const schema={
 assets:[['tag','TAG / código','text',true],['name','Nome da máquina','text',true],['production_line','Linha de produção','production-lines'],['area','Área legada (opcional)','text'],['criticality','Criticidade','select',['A','B','C']],['manufacturer','Fabricante'],['model','Modelo'],['serial','Número de série'],['notes','Observações','textarea']],
 team:[['name','Nome','text',true],['specialty','Especialidade','select',['Mecânica','Elétrica','Instrumentação','Automação','Multidisciplinar']],['shift','Turno','select',shifts],['hours_day','Horas totais de trabalho por dia','number',true],['productivity_rate','Taxa de produtividade (%)','number',true],['days_week','Dias de trabalho por semana','number',true],['active','Situação','boolean']],
 materials:[['code','Código','text',true],['name','Descrição','text',true],['unit','Unidade'],['quantity','Saldo atual','number'],['minimum','Estoque mínimo','number'],['unit_cost','Valor unitário (R$)','number'],['location','Localização']],
 projects:[['name','Nome do cronograma','text',true],['owner','Coordenador'],['start','Início da janela','date',true],['end','Fim da janela','date',true],['notes','Escopo e observações','textarea']],
 plans:[['name','Nome da rotina','text',true],['asset_id','Ativo','assets',true],['type','Estratégia','select',types],['interval_days','Periodicidade em dias','number',true],['next_date','Próxima ocorrência','date',true],['hours','Esforço estimado (HH)','number',true],['specialty','Especialidade'],['active','Situação','boolean'],['checklist','Procedimento / roteiro (uma etapa por linha)','textarea']],
 orders:[['title','Atividade / título da OS','text',true],['asset_id','Ativo','assets',true],['type','Tipo de manutenção','select',types],['priority','Prioridade','select',[['P1','P1 · Crítica'],['P2','P2 · Alta'],['P3','P3 · Normal'],['P4','P4 · Baixa']]],['requested_date','Data da solicitação','date',true],['due_date','Prazo desejado','date'],['description','Descrição da necessidade / escopo','textarea'],['estimated_hours','Esforço estimado (HH)','number',true],['shift','Turno de execução','select',shifts],['scheduled_date','Data programada','date'],['assignee_id','Executante responsável','team'],['project_id','Cronograma de parada','projects'],['blocker','Material pendente / impedimento'],['checklist','Procedimento / roteiro e evidências','textarea'],['actual_hours','Horas reais trabalhadas (HH)','number'],['labor_rate','Custo por HH (R$)','number'],['material_cost','Custo de materiais consumidos (R$)','number'],['downtime_hours','Tempo de parada do equipamento (h)','number'],['failure','Falha identificada'],['cause','Causa (ou Em análise)'],['action','Serviço realizado / justificativa','textarea'],['completed_date','Data de conclusão','date']]
};
function fieldHTML(spec,value){const [key,label,type='text',extra]=spec,required=extra===true,req=required?'required':'';let control;if(type==='production-lines'){const lines=[...new Set([...state.assets.map(a=>a.production_line),...(value?[value]:[])].filter(Boolean))].sort();control=`<input name="${key}" id="f-${key}" list="production-lines-list" value="${esc(value)}" placeholder="Digite ou selecione uma linha"><datalist id="production-lines-list">${lines.map(line=>`<option value="${esc(line)}">`).join('')}</datalist>`;}else if(['assets','team','projects'].includes(type)){let list=state[type].filter(r=>type!=='team'||r.active||r.id==value).map(r=>[r.id,type==='assets'?`${r.tag} · ${r.name} (${r.production_line||r.area||'sem linha'})`:type==='team'?`${r.name} · ${r.shift}`:r.name]);control=`<select name="${key}" id="f-${key}" ${req}>${options(list,value,'Selecione…')}</select>`;}else if(type==='select'){control=`<select name="${key}" id="f-${key}">${options(extra,value,null)}</select>`;}else if(type==='boolean'){control=`<select name="${key}" id="f-${key}">${options([['true','Ativo'],['false','Inativo']],String(value??true),null)}</select>`;}else if(type==='textarea'){control=`<textarea name="${key}" id="f-${key}" rows="3" ${req}>${esc(value)}</textarea>`;}else{control=`<input name="${key}" id="f-${key}" type="${type}" value="${esc(value)}" ${req} ${key==='productivity_rate'?'max="100"':''} ${type==='number'?'min="0" step="any"':''}>`;}return `<div class="field ${type==='textarea'?'full':''}"><label for="f-${key}">${label}${required?' *':''}</label>${control}</div>`;}
function showModal(content){$('#modal-content').innerHTML=content;if(!$('#modal').open)$('#modal').showModal();}
function showForm(tableName,id,nextStatus){const record=id?state[tableName].find(r=>r.id==id):null;if(id&&!record)return toast('Registro não encontrado. Atualize a página.');const defaults={orders:{type:'Preventiva',priority:'P3',status:'Aberta',requested_date:today(),estimated_hours:2,actual_hours:0,labor_rate:0,material_cost:0,downtime_hours:0,shift:'1º turno'},plans:{type:'Preventiva',interval_days:30,next_date:today(),hours:2,active:true},team:{specialty:'Mecânica',hours_day:8,productivity_rate:100,days_week:5,shift:'1º turno',active:true},assets:{criticality:'B',production_line:''},materials:{unit:'un',quantity:0,minimum:0,unit_cost:0},projects:{start:today(),end:today()}};const data={...defaults[tableName],...record};if(tableName==='assets'&&!record)data.production_line=buttonLineOverride||'';if(nextStatus){data.status=nextStatus;if(nextStatus==='Concluída')data.completed_date=today();}const name={orders:'ordem de serviço',assets:'máquina',team:'profissional',plans:'plano de manutenção',projects:'cronograma',materials:'material'}[tableName];let fields=schema[tableName];if(tableName==='orders'&&!record)fields=fields.filter(s=>!['scheduled_date','assignee_id','actual_hours','labor_rate','material_cost','downtime_hours','failure','cause','action','completed_date'].includes(s[0]));
const flow=tableName==='orders'&&record?`<div class="flow-bar">${['Aberta','Programada','Em execução','Concluída'].map((s,i)=>`<span class="${data.status===s?'current':''}">${i+1}. ${s}</span>`).join('')}</div><div class="note">Situação: <strong>${esc(data.status)}</strong>. ${data.status==='Concluída'?'O fechamento entra nos indicadores pela data de conclusão. Correções de apontamento podem ser salvas.':'Salve os dados antes de avançar. Para cancelar, informe a justificativa.'}</div>`:'';
const statusField=tableName==='orders'?`<input type="hidden" name="status" value="${esc(data.status)}">`:'';
if(tableName==='orders'&&!['Em execução','Concluída','Cancelada'].includes(data.status))fields=fields.filter(s=>!['actual_hours','labor_rate','material_cost','downtime_hours','failure','cause','action','completed_date'].includes(s[0]));
if(tableName==='orders'&&data.status!=='Concluída')fields=fields.filter(s=>s[0]!=='completed_date');
const workflow=tableName==='orders'&&record&&!nextStatus&&transitions[record.status].length?`<div class="workflow-actions"><strong>Avançar atendimento</strong><div class="actions">${transitions[record.status].map(s=>btn(({'Em planejamento':'Planejar','Aguardando material':'Aguardar material','Programada':'Programar','Em execução':'Iniciar execução','Concluída':'Concluir OS','Cancelada':'Cancelar OS'})[s],'transition',s==='Cancelada'?'danger':'',`data-id="${id}" data-status="${s}"`)).join('')}</div><small>Os botões abrem a etapa para revisão. O avanço acontece ao salvar.</small></div>`:'';
showModal(`<div class="modal-head"><div><div class="eyebrow">${id?tableName==='orders'?osCode(id):'CADASTRO':'NOVO REGISTRO'}</div><h2>${id?'Editar':tableName==='orders'?'Nova':'Novo'} ${name}</h2></div><button class="icon-button" data-action="close" aria-label="Fechar">×</button></div>${workflow}<form id="record-form" data-table="${tableName}" data-id="${id||''}"><div class="modal-body">${flow}${!id&&tableName==='orders'?'<div class="note">A OS será aberta na carteira. Depois de salvar, use <strong>Programar</strong> para atribuir data e executante.</div>':''}${statusField}<div class="form-grid">${fields.map(s=>fieldHTML(s,data[s[0]]??'')).join('')}</div>${tableName==='team'?'<div class="note" id="productivity-preview" aria-live="polite"></div>':''}<div id="form-error" class="form-error" role="alert"></div></div><div class="modal-actions">${id&&tableName!=='orders'?btn('Excluir','delete','danger',`data-table="${tableName}" data-id="${id}" type="button"`):''}${btn('Voltar','close','', 'type="button"')}<button class="btn primary" type="submit">${nextStatus==='Concluída'?'Confirmar fechamento':nextStatus?'Salvar · '+esc(nextStatus):'Salvar registro'}</button></div></form>`);
const form=$('#record-form');form._original=record;form._dirty=false;form.addEventListener('input',()=>form._dirty=true);form.addEventListener('change',()=>form._dirty=true);$('#modal-content').scrollTop=0;
if(tableName==='team'){const update=()=>{$('#productivity-preview').textContent=`Meta diária: ${num(Number($('#f-hours_day').value)*Number($('#f-productivity_rate').value)/100)} h produtivas. Horas totais × taxa de produtividade ÷ 100. Cadastros antigos usam 100% até você ajustar a taxa.`;};form.addEventListener('input',update);update();}
if(tableName==='orders'){$('#f-assignee_id')?.addEventListener('change',e=>{const t=person(e.target.value);if(t)$('#f-shift').value=t.shift;});}
}
async function submitRecord(form){const button=$('button[type="submit"]',form);button.disabled=true;$('#form-error').textContent='';try{const tableName=form.dataset.table,id=form.dataset.id,data={...(form._original||{})};new FormData(form).forEach((value,key)=>{const spec=schema[tableName].find(s=>s[0]===key);data[key]=spec?.[2]==='number'?Number(value||0):spec?.[2]==='boolean'?value==='true':value;});const result=await api(tableName+(id?'/'+id:''),id?'PUT':'POST',data);$('#modal').close();await refresh();toast(data.status==='Concluída'?'OS concluída. Backlog e indicadores atualizados.':'Registro salvo com sucesso.');if(tableName==='orders')showForm('orders',result.id);}catch(error){if($('#form-error'))$('#form-error').textContent=error.message;else toast(error.message);}finally{button.disabled=false;}}
function help(){showModal(`<div class="modal-head"><h2>Um fluxo simples, do pedido à entrega</h2><button class="icon-button" data-action="close" aria-label="Fechar">×</button></div><div class="modal-body help-body"><ol><li><strong>Cadastre ativos e equipe.</strong> Identifique a célula ou linha do equipamento e o turno de cada executante.</li><li><strong>Abra uma OS.</strong> Defina a necessidade, prioridade, prazo e esforço estimado. Ela passa a compor o backlog.</li><li><strong>Planeje e programe.</strong> Detalhe o roteiro, materiais e impedimentos. Use Programar para escolher data e responsável. O turno acompanha o cadastro do técnico.</li><li><strong>Inicie a execução.</strong> Uma OS programada pode avançar para Em execução.</li><li><strong>Conclua com evidências.</strong> Registre horas reais, custos, serviço realizado e data. Corretivas também precisam de falha e causa.</li><li><strong>Confira os resultados.</strong> A OS sai do backlog e entra nos indicadores do período de conclusão. O histórico mantém as alterações.</li></ol><div class="note">Uso individual e local, com SQLite. Os dados continuam salvos após fechar a página. Execute Iniciar PCM.cmd para abrir novamente. A base inicial é demonstrativa.</div></div>`);}
function download(name,content,type){const link=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function printSelectedOrders(){const orders=state.orders.filter(o=>selectedOrderIds.has(o.id));if(!orders.length){toast('Selecione pelo menos uma ordem para imprimir.');return;}const cards=orders.map(o=>{const a=asset(o.asset_id),assignee=person(o.assignee_id);return `<article class="order"><header><div><small>ORDEM DE SERVIÇO</small><h1>${osCode(o.id)}</h1></div><div class="status">${esc(o.status)} · ${esc(o.priority)}</div></header><h2>${esc(o.title)}</h2><dl><div><dt>Ativo</dt><dd>${esc(a?.tag||'—')} · ${esc(a?.name||'Não informado')}</dd></div><div><dt>Linha / área</dt><dd>${esc(a?.production_line||a?.area||'Não informada')}</dd></div><div><dt>Tipo</dt><dd>${esc(o.type)}</dd></div><div><dt>Programação</dt><dd>${dateLabel(o.scheduled_date)} · ${esc(o.shift||'—')}</dd></div><div><dt>Prazo</dt><dd>${dateLabel(o.due_date)}</dd></div><div><dt>HH previstos</dt><dd>${num(o.estimated_hours)} HH</dd></div><div><dt>Horário de início</dt><dd class="write-line">&nbsp;</dd></div><div><dt>Horário final</dt><dd class="write-line">&nbsp;</dd></div><div><dt>Técnico responsável</dt><dd>${esc(assignee?.name||'')}<br><span class="write-line">Nome: </span></dd></div><div><dt>Avaliador</dt><dd><span class="write-line">Nome: </span></dd></div></dl><section class="writing"><h3>Descrição do serviço / serviço executado</h3><p>${esc(o.description||'').replace(/\n/g,'<br>')}</p></section><section class="writing"><h3>Materiais utilizados</h3><p>${esc(o.materials||o.blocker||'').replace(/\n/g,'<br>')}</p></section><section class="writing"><h3>Anormalidades encontradas</h3><p>&nbsp;</p></section><div class="signatures"><span>Nome e assinatura do técnico<br><br>________________________________</span><span>Nome e assinatura do avaliador<br><br>________________________________</span></div></article>`;}).join('');const printWindow=window.open('','_blank');if(!printWindow){throw new Error('O navegador bloqueou a janela de impressão. Permita pop-ups para este endereço e tente novamente.');}printWindow.opener=null;printWindow.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Ordens de serviço</title><style>@page{size:A4;margin:12mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#17333a;margin:0}.order{break-after:page;border:1px solid #b8cbd0;padding:10mm;min-height:273mm}.order:last-child{break-after:auto}header{display:flex;justify-content:space-between;border-bottom:2px solid #007f79;padding-bottom:5mm}header small{letter-spacing:1.5px;color:#007f79;font-weight:bold}h1{margin:4px 0 0;font-size:24px}h2{font-size:18px;margin:6mm 0 5mm}.status{font-size:12px;font-weight:bold;padding-top:5mm}dl{display:grid;grid-template-columns:1fr 1fr;gap:3mm 7mm;margin:0}dt{font-size:9px;text-transform:uppercase;color:#64777d;font-weight:bold}dd{margin:1px 0 0;font-size:11px;line-height:1.35;min-height:7mm}.write-line{display:block;border-bottom:1px solid #8da2a8;min-height:5mm}section{margin-top:4mm;border:1px solid #c8d7da;padding:3mm}h3{font-size:10px;text-transform:uppercase;color:#007f79;margin:0 0 2mm}p{font-size:11px;line-height:1.45;margin:0;min-height:20mm}.writing p{min-height:25mm}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:16mm;margin-top:7mm}.signatures span{font-size:10px;line-height:1.3;text-align:center}</style></head><body>${cards}<script>window.addEventListener('load',()=>window.print());<\/script></body></html>`);printWindow.document.close();}
function importOrders(){showModal(`<div class="modal-head"><div><div class="eyebrow">DADOS MESTRES</div><h2>Importar ordens de serviço</h2></div><button class="icon-button" data-action="close" aria-label="Fechar">×</button></div><div class="modal-body"><p class="subtitle">Baixe o modelo, preencha uma linha por OS e importe o arquivo. O ativo deve usar uma tag já cadastrada; o responsável, quando informado, deve estar cadastrado e no mesmo turno.</p><div class="actions" style="margin:18px 0">${btn('Baixar modelo Excel','download-orders-template','primary')}</div><label class="field"><span>Arquivo preenchido (.xlsx, até 5 MB)</span><input id="orders-import-file" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"></label><div id="orders-import-result" class="note" aria-live="polite">Dados mestres atuais: ${state.assets.length} ativos e ${state.team.length} profissionais.</div></div><div class="modal-actions">${btn('Voltar','close','','type="button"')}<button id="confirm-orders-import" class="btn primary" type="button" disabled>Validar e importar</button></div>`);$('#confirm-orders-import').addEventListener('click',async()=>{const file=$('#orders-import-file').files[0],result=$('#orders-import-result'),button=$('#confirm-orders-import');if(!file)return;button.disabled=true;try{result.textContent='Lendo e validando o arquivo…';const orders=PCMOrderImport.validate(await PCMOrderImport.read(file),state);result.textContent=`${orders.length} OS válida(s). Criando registros…`;const saved=await api('orders/import','POST',{orders});$('#modal').close();await refresh();toast(`${saved.count} ordem(ns) importada(s) com sucesso.`);}catch(error){result.textContent=error.message;result.classList.add('warning');button.disabled=false;}});$('#orders-import-file').addEventListener('change',e=>{$('#confirm-orders-import').disabled=!e.target.files[0];$('#orders-import-result').textContent=e.target.files[0]?'Arquivo selecionado. Clique em “Validar e importar”.':`Dados mestres atuais: ${state.assets.length} ativos e ${state.team.length} profissionais.`;});}
async function confirmation(title,message,required,callback){showModal(`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="Fechar">×</button></div><form id="confirm-form"><div class="modal-body"><p>${esc(message)}</p><label for="confirm-text">Digite <strong>${esc(required)}</strong> para confirmar.</label><input id="confirm-text" autocomplete="off" required><div class="form-error" id="form-error" role="alert"></div></div><div class="modal-actions">${btn('Voltar','close','','type="button"')}<button class="btn danger" type="submit">Confirmar</button></div></form>`);$('#confirm-form').addEventListener('submit',async e=>{e.preventDefault();if($('#confirm-text').value!==required){$('#form-error').textContent='A confirmação não corresponde ao texto solicitado.';return;}const b=$('button[type="submit"]',e.target);b.disabled=true;try{await callback();$('#modal').close();await refresh();toast('Operação concluída.');}catch(error){$('#form-error').textContent=error.message;b.disabled=false;}});}
document.addEventListener('submit',e=>{if(e.target.id==='record-form'){e.preventDefault();submitRecord(e.target);}});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;try{
if(action==='new'){buttonLineOverride=button.dataset.line||'';showForm(button.dataset.table);buttonLineOverride='';}
if(action==='edit')showForm(button.dataset.table,Number(button.dataset.id));
if(action==='close'){const form=$('#record-form');if(form?._dirty){if(!confirm('Descartar as alterações não salvas deste formulário?'))return;}$('#modal').close();}
if(action==='help')help();
if(action==='reload')await refresh();
if(action==='transition'){if($('#record-form')?._dirty){$('#form-error').textContent='Salve as alterações do formulário antes de avançar para outra etapa.';toast('Salve as alterações antes de avançar.');return;}showForm('orders',Number(button.dataset.id),button.dataset.status);}
if(action==='clear-filters'){filters={text:'',status:'',area:'',shift:''};period={start:today().slice(0,8)+'01',end:today()};await render();}
if(action==='clear-plan-filters'){planFilters={text:'',line:'',specialty:''};await render();}
if(action==='clear-asset-filters'){assetFilters={text:'',line:'',criticality:''};await render();}
if(action==='schedule-view'){scheduleView=button.dataset.view;await render();}
if(action==='open-month'){scheduleDate=button.dataset.date;scheduleView='month';await render();}
if(action==='schedule-today'){scheduleDate=today();await render();}
if(action==='period-next'||action==='period-prev'){const dir=action==='period-next'?1:-1,d=new Date(scheduleDate+'T12:00:00');if(scheduleView==='year'){d.setFullYear(d.getFullYear()+dir);scheduleDate=iso(d);}else if(scheduleView==='month'){d.setDate(1);d.setMonth(d.getMonth()+dir);scheduleDate=iso(d);}else scheduleDate=plus(scheduleDate,dir*(scheduleView==='week'?7:1));await render();}
if(action==='print')window.print();
if(action==='print-selected-orders')printSelectedOrders();
if(action==='import-orders')importOrders();
if(action==='download-orders-template'){PCMOrderImport.template(state);toast('Modelo Excel com listas dos dados mestres baixado.');}
if(action==='generate'){const p=state.plans.find(p=>p.id==button.dataset.id);button.disabled=true;const result=await api(`plans/${p.id}/generate`,'POST',{expected_date:p.next_date});await refresh();toast(`${osCode(result.id)} criada. Defina a programação.`);showForm('orders',result.id);}
if(action==='export-orders'||action==='export-orders-excel'){const rows=[['OS','Atividade','TAG máquina','Máquina','Linha de produção','Tipo','Prioridade','Situação','Turno','Solicitação','Programação','Conclusão','HH previstos','HH reais','Custo realizado'],...visibleOrders().map(o=>[osCode(o.id),o.title,asset(o.asset_id)?.tag,asset(o.asset_id)?.name,asset(o.asset_id)?.production_line||asset(o.asset_id)?.area,o.type,o.priority,o.status,o.shift,o.requested_date,o.scheduled_date,o.completed_date,o.estimated_hours,o.actual_hours,o.status==='Concluída'?o.actual_hours*o.labor_rate+o.material_cost:0])];if(action==='export-orders-excel'){download(`PCM-ordens-${today()}.xlsx`,PCMExcel.build(rows),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');toast('Exportação Excel concluída com os filtros atuais.');return;}const csv=rows.map(row=>row.map(v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(';')).join('\r\n');download(`PCM-ordens-${today()}.csv`,'\uFEFF'+csv,'text/csv;charset=utf-8');toast('Exportação concluída com os filtros atuais.');}
if(action==='backup'){download(`PCM-backup-${today()}.json`,JSON.stringify(await api('backup'),null,2),'application/json');toast('Backup exportado.');}
if(action==='restore')$('#restore-file').click();
if(action==='clear-demo')await confirmation('Iniciar uma base vazia','Todos os cadastros e ordens desta base serão removidos, inclusive os que você adicionou. Exporte um backup antes.','LIMPAR DEMONSTRAÇÃO',()=>api('clear-demo','POST',{confirmation:'LIMPAR DEMONSTRAÇÃO'}));
if(action==='delete')await confirmation('Excluir registro','A exclusão é permanente. Registros vinculados a ordens ou planos não podem ser excluídos.','EXCLUIR',()=>api(`${button.dataset.table}/${button.dataset.id}`,'DELETE'));
}catch(error){toast(error.message);}finally{if(button.isConnected)button.disabled=false;}});
document.addEventListener('change',async e=>{const id=e.target.id;try{if(e.target.matches('.order-select')){const orderId=Number(e.target.dataset.orderId);e.target.checked?selectedOrderIds.add(orderId):selectedOrderIds.delete(orderId);await render();return;}if(id==='select-all-orders'){const rows=visibleOrders();if(e.target.checked)rows.forEach(o=>selectedOrderIds.add(o.id));else rows.forEach(o=>selectedOrderIds.delete(o.id));await render();return;}if(id==='asset-line-filter'||id==='asset-criticality-filter'){assetFilters[id==='asset-line-filter'?'line':'criticality']=e.target.value;await render();return;}if(id==='plans-line-filter'||id==='plans-specialty-filter'){planFilters[id==='plans-line-filter'?'line':'specialty']=e.target.value;await render();return;}if(['area-filter','shift-filter','status-filter'].includes(id)){filters[id==='area-filter'?'area':id.split('-')[0]]=e.target.value;await render();}if(id==='annual-year'){annualYear=Number(e.target.value);annualWeek='';await render();}if(id==='annual-week'){annualWeek=e.target.value;await render();}if(id==='schedule-date'&&e.target.value){scheduleDate=e.target.value;await render();}if(id==='period-start'||id==='period-end'){const key=id.split('-')[1],next={...period,[key]:e.target.value};if(!next.start||!next.end||next.start>next.end){toast('Selecione um período válido: início anterior ou igual ao fim.');e.target.value=period[key];return;}period=next;await render();}if(id==='restore-file'&&e.target.files[0]){const f=e.target.files[0];if(f.size>5000000)throw new Error('Backup maior que 5 MB.');const payload=JSON.parse(await f.text());if(payload.format!=='pcm-backup-v1')throw new Error('Formato de backup inválido.');await confirmation('Restaurar backup','A restauração substitui todos os cadastros e ordens atuais. Faça uma cópia de segurança antes.','RESTAURAR',()=>api('restore','POST',payload));}}catch(error){toast(error.message);}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search'||e.target.id==='asset-search'||e.target.id==='plans-search'){const isAsset=e.target.id==='asset-search',isPlan=e.target.id==='plans-search';if(isAsset)assetFilters.text=e.target.value;else if(isPlan)planFilters.text=e.target.value;else filters.text=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{const at=e.target.selectionStart;await render();const input=$(isAsset?'#asset-search':isPlan?'#plans-search':'#search');input?.focus();input?.setSelectionRange(at,at);},220);}});
$('#help').addEventListener('click',help);$('#menu').addEventListener('click',()=>document.body.classList.toggle('menu-open'));
$('#modal').addEventListener('cancel',e=>{if($('#record-form')?._dirty&&!confirm('Descartar alterações não salvas?'))e.preventDefault();});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'dashboard';if(!modules.some(m=>m[0]===page))page='dashboard';filters={text:'',status:'',area:'',shift:''};document.body.classList.remove('menu-open');window.scrollTo(0,0);render();});
$('#today').textContent=new Date().toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'});
page=location.hash.slice(1)||'dashboard';refresh().catch(error=>{$('#main').innerHTML=heading('Servidor indisponível',esc(error.message))+btn('Tentar novamente','reload');});

