fieldHTML=function(spec,value){if(spec[0]!=='asset_id'||spec[2]!=='assets')return fieldHTMLOriginal(spec,value);const selected=state.assets.find(a=>String(a.id)===String(value)),label=selected?`${selected.tag} · ${selected.name} (${selected.production_line||selected.area||'sem linha'})`:'';return `<div class="field"><label for="f-asset-search">Ativo *</label><input id="f-asset-search" type="search" list="asset-search-options" value="${esc(label)}" placeholder="Digite TAG, nome ou linha…" autocomplete="off" required><input type="hidden" name="asset_id" id="f-asset_id" value="${esc(value||'')}"><datalist id="asset-search-options">${state.assets.map(a=>`<option value="${esc(`${a.tag} · ${a.name} (${a.production_line||a.area||'sem linha'})`)}" data-id="${a.id}"></option>`).join('')}</datalist><small class="field-help">Digite para filtrar e selecione uma máquina cadastrada.</small></div>`;};
